.box-model-demo {
  /* 1. Content layer: width and height define the core inner content area */
  width: 300px;
  height: 150px;

  /* 2. Padding layer: clear space between content and border */
  padding: 24px;

  /* 3. Border layer: visual boundary surrounding the padding */
  border: 4px solid #3b82f6;

  /* 4. Margin layer: transparent clearance outside the border separating adjacent elements */
  margin: 32px auto;

  background-color: #f0f9ff;
}

p.first {
  /* Bottom margin of 30px */
  margin-bottom: 30px;
}

p.second {
  /* Top margin of 20px */
  margin-top: 20px;
}

/* 
 * Resulting vertical distance between paragraphs is NOT 50px (30 + 20)!
 * Instead, the margins collapse into each other.
 * The browser takes the LARGEST single margin: max(30px, 20px) = 30px.
 * Thus, the actual vertical separation between the two paragraphs is exactly 30px.
 */

.page-wrapper {
  width: 100%;
  background-color: #f3f4f6;
}

.centered-card {
  /* Must have an explicit width or max-width less than parent */
  width: 100%;
  max-width: 600px;

  /* auto on left and right distributes remaining horizontal space equally */
  margin: 2rem auto;

  padding: 2rem;
  background-color: #ffffff;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}
